      beijing = 1132,
      dialog = 3,
      music = "23_Lonely",
      renwu = "npc",
      ruchang = 0,
      sentence = "I immediately stopped in my tracks. I turned to see Lucien on the screen giving a speech at a press conference, one that I had heard in person before.",
